package org.apache.shenyu.plugin.agent.gateway.security;

import java.security.Principal;
import java.util.Objects;

/**
 * Server-owned identity marker. Only verified authentication adapters create it.
 * Ordinary principals, request headers and client metadata are not equivalent.
 */
public final class AgentMcpPrincipal implements Principal {

    private final AgentMcpIdentity identity;

    public AgentMcpPrincipal(final AgentMcpIdentity identity) {
        this.identity = Objects.requireNonNull(identity, "identity");
    }

    @Override
    public String getName() {
        return identity.getSubject();
    }

    public AgentMcpIdentity getIdentity() {
        return identity;
    }
}

